    "advicePendingTitle": "Noch nicht gezeigte Tipps",
    "advicePendingSubtitle": "{count} Tipp(s) als relevant markiert, aber noch nicht angesehen",
    "advicePendingEmpty": "Alle relevanten Tipps wurden angesehen.",
    "adviceTitle": "Relevante Tipps",
