    "advicePendingTitle": "Consejos aún no mostrados",
    "advicePendingSubtitle": "{count} consejo(s) marcado(s) como relevante(s) pero aún no visto(s)",
    "advicePendingEmpty": "Todos los consejos relevantes han sido vistos.",
    "adviceTitle": "Consejos relevantes",
