    "advicePendingTitle": "Dicas ainda não mostradas",
    "advicePendingSubtitle": "{count} dica(s) marcada(s) como relevante(s) mas ainda não visualizada(s)",
    "advicePendingEmpty": "Todas as dicas relevantes foram visualizadas.",
    "adviceTitle": "Dicas relevantes",
